import json,urllib.request
base="http://127.0.0.1:17448"
out={}
for path in ("/api/supervisor-watchdog","/api/supervisor-watchdog/status","/api/supervisor-watchdog/config","/api/supervisor-watchdog/managed-chats"):
 try:
  with urllib.request.urlopen(base+path,timeout=4) as r:
   data=json.loads(r.read(300000).decode("utf8"))
  if not isinstance(data,dict):
   out[path]={"http":200,"shape":type(data).__name__}
   continue
  key=["mode","state","enabled","isRunning","allowAutonomousSend","reconciliationRequired","isPaused","paused","startedAt","error","dispatchEnabled","status","watchdog","control","config"]
  safe={}
  for k in key:
   v=data.get(k)
   if isinstance(v,(bool,int)) or v is None:safe[k]=v
   elif isinstance(v,str) and k in ("mode","state","status"):safe[k]=v[:80]
   elif isinstance(v,dict) and k in ("watchdog","control","config"):
    safe[k]={a:b for a,b in v.items() if a in ("mode","state","enabled","allowAutonomousSend","reconciliationRequired","running","paused") and isinstance(b,(bool,int,str))}
  if path.endswith("managed-chats"):
   m=[x for x in data.get("chats",[]) if x.get("id")=="tg-curator-owner"]
   safe["curator"]=[{k:v for k,v in x.items() if k in ("id","enabled","dispatchEnabled","allowAutonomousSend","paused","state","mode") and isinstance(v,(bool,str))} for x in m]
   safe["total_chats"]=len(data.get("chats",[]))
  out[path]={"http":200,"top_keys":list(data.keys())[:45],"selected":safe}
 except urllib.error.HTTPError as e:out[path]={"http":e.code}
 except Exception as e:out[path]={"error_type":type(e).__name__}
print(json.dumps(out,ensure_ascii=True))
